import{planTotals,policies,pyramidMasses,supplyResult}from './eco5-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const T=(x,y,s,n=17,c='#faf5ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;const L=(a,b,c='#bdd1cb',w=3)=>`<path d="M${a[0]} ${a[1]}L${b[0]} ${b[1]}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const C=(x,y,r=7,c='#efb094')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const B=(x,y,w,h,c='#365463')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" fill="${c}" stroke="#a8c4be"/>`;export const eco5SVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${a}</svg>`;
export function pyramidFigure({masses=pyramidMasses,scale=1000,base='producers'}={}){scale=Number.isFinite(scale)&&scale>0?scale:1000;let a=T(280,28,'One common scale for every biomass bar',22),out=false,labels=['1 Producer','2 Primary','3 Secondary','4 Tertiary'];for(let i=0;i<4;i++){let v=masses[i],valid=v!==''&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0,n=valid?Number(v):0,y=base==='tertiary'?106+i*68:310-i*68;a+=T(280,y-10,labels[i]+': '+(valid?n:'—')+' g/m²',15);if(valid){if(n>scale)out=true;let width=Math.min(n,scale)/scale*440;a+=`<rect x="${280-width/2}" y="${y}" width="${width}" height="30" fill="${['#a8c4ae','#c8bf9b','#d2ac97','#b7bed3'][i]}" stroke="#e1ddd1"/>`;}}if(out)a+=T(280,62,'Value outside scale: choose a fitting common scale',14,'#ffd0ae');a+=T(280,385,'Full reference width = '+scale+' g/m²',17)+T(280,411,'Equal heights · widths encode biomass, not organism count',14)+T(280,433,'Original data · very narrow bars remain proportional',13);return eco5SVG(a,'Biomass pyramid values '+masses.join(',')+' g/m² at levels1–4. Full common width '+scale+' g/m². Base '+base+'. '+(out?'Some values exceed the scale; widths clipped and flagged. ':'')+'Not individual numbers or energy.');}
export function planFigure({selected=[]}={}){let n=planTotals(selected),a=T(280,30,'Meet the stated goals within10 credits',23);for(let[i,k]of Object.keys(policies).entries()){let p=policies[k];a+=B(35+i*175,85,155,95,selected.includes(k)?'#587a6a':'#344e5f')+T(112+i*175,120,p.label,15)+T(112+i*175,154,selected.includes(k)?'✓ Selected':'Not selected',15);}for(let[i,[label,val,target,unit]]of[['Cost',n.cost,10,'credits'],['Habitat',n.habitat,4,'ha'],['Waste diverted',n.waste,20,'tonnes']].entries()){let y=235+i*55;a+=T(130,y,label,16)+T(370,y,val+' '+unit+' / '+(i===0?'maximum':'minimum')+' '+target,15);}a+=T(280,410,'Original costs/outcomes · specific targets, not universal value',13)+T(280,433,'Breeding may benefit species outside these habitat/waste goals',12);return eco5SVG(a,`Original conservation plan: ${selected.join(',')||'none'}. Cost ${n.cost}/10 credits, habitat ${n.habitat}ha target4, diverted waste ${n.waste}tonnes target20. Not a real policy appraisal or species-survival model.`);}
export function feedingFigure(p=0){let a=T(280,30,'Number feeding positions, starting at the producer',21),xs=[70,210,350,490],names=['Grass','Grasshopper','Frog','Hawk'];for(let[i,x]of xs.entries()){a+=B(x-53,100,106,135)+T(x,139,names[i],15)+T(x,180,'Level '+(i+1),20)+T(x,213,i?'Consumer':'Producer',13);if(i<3)a+=L([x+54,165],[x+84,165])+`<path d="M${x+76} 157l8 8 -8 8" fill="none" stroke="#bdd1cb"/>`;}a+=C(70+420*p,165,7)+T(280,300,'Food → consumer · apex predator in this supplied route',17)+T(280,350,'A species can occupy different positions in a food web',16)+T(280,423,'Original symbolic chain · marker is a transfer signal, not an animal',12);return eco5SVG(a,'Original grass→grasshopper→frog→hawk chain; trophic levels1,2,3,4. Signal traces food transfer, not an organism becoming another. Hawk has no predator shown in this route.');}
export function decomposerFigure(p=0){let phase=Math.min(2,Math.floor(p*3)),a=T(280,30,'Digest outside, then absorb soluble products',22)+`<ellipse cx="435" cy="225" rx="92" ry="125" fill="#61857c" stroke="#c5d8ca" stroke-width="4"/>`+T(435,225,'Microorganism',15)+T(435,250,'Cell surface',13)+T(155,95,'Dead organic material',17);for(let i=0;i<5;i++)a+=C(75+i*35,170+(phase===1?i%2*25:0),phase===0?15:7,'#e4be98');a+=T(155,260,phase===0?'Large food molecules':'Small soluble products',16);let q=p*3%1;if(phase===0)a+=`<path d="M${345-100*q} 310l-10 -10 10 -10 10 10z" fill="#bfc2df"/>`+T(200,350,'Enzyme secreted into surroundings',17);else if(phase===1)a+=T(280,350,'Enzymes break down large molecules outside',17);else a+=C(220+180*q,190,6,'#e4be98')+T(280,350,'Soluble products diffuse across the cell surface',16);a+=T(280,412,'Diamond: enzyme · peach beads: food/products',14)+T(280,433,'Separately enlarged · symbolic route, not molecular speed/size',12);return eco5SVG(a,'Decomposer nutrition: enzymes secreted outside; large food molecules digested into small soluble products; products diffuse into the microorganism. Enzyme and product markers differ in shape. Not engulfing intact debris; symbolic dimensions/timing.');}
export function allocationFigure({allocation={faeces:20,respired:70,growth:10},progress=1}={}){let a=T(280,28,'Track the original organic material',23),vals=['faeces','respired','growth'].map(k=>allocation[k]!==''&&allocation[k]!==undefined&&Number.isFinite(Number(allocation[k]))&&Number(allocation[k])>=0?Number(allocation[k]):0),total=vals.reduce((a,b)=>a+b),x=50,colors=['#b5c4ce','#d3bca0','#9fc3ad'];a+=T(280,82,'100 consumed organic-material units',19);for(let[i,v]of vals.entries()){let width=Math.min(v,100)*4.6*progress;a+=`<rect x="${x}" y="140" width="${width}" height="70" fill="${colors[i]}"/>`;x+=width;a+=T(280,265+i*40,['Unabsorbed → faeces','Organic substrate used in respiration','Retained as new biomass'][i]+': '+v,16);}if(total!==100)a+=T(280,110,'Account total '+total+'; original total100',16,'#ffd0ae');a+=T(280,415,'Organic-material allocation, not complete product/gas masses',13)+T(280,435,'Incoming oxygen, urinary and other routes omitted in this toy account',12);return eco5SVG(a,'Original organic-material account: unabsorbed '+vals[0]+', respired substrate '+vals[1]+', growth '+vals[2]+', total '+total+' of100 consumed units. Tracks original organic material, not gas-product mass after oxygen enters. Other routes omitted.');}
export function supplyFigure({scenario='baseline',revealed=true}={}){let s=supplyResult(scenario),a=T(280,30,'Compare accessible food with demand',22)+T(280,68,s.label+' ·'+s.population+' people ×2 units each',17);for(let[i,[name,v,col]]of[['Produced',s.produced,'#adbacb'],['Accessible',s.available,'#c7c39e'],['Demand',s.demand,'#e7b199']].entries()){let y=130+i*70;a+=T(88,y+25,name,15)+`<rect x="160" y="${y}" width="${v}" height="36" rx="6" fill="${col}"/>`+T(490,y+25,v,18);}a+=T(280,370,revealed?'Shortfall '+s.shortfall+' · surplus '+s.surplus+' units':'Predict the shortfall, then reveal',19)+T(280,410,'Original food-equivalent units · not calories or a nutrition prescription',12)+T(280,434,'Aggregate account omits individual distribution and dietary needs',13);return eco5SVG(a,`Fictional ${s.label}: ${s.population}people,2 units each, demand ${s.demand}; produced ${s.produced}, accessible ${s.available}. `+(revealed?`Shortfall ${s.shortfall}, surplus ${s.surplus}. `:'Predict the deficit. ')+'Not measured food statistics or proof everyone receives adequate nutrition.');}
const rows={conservation:['Breed endangered species; protect/regenerate habitats','Restore margins/hedgerows in monoculture','Reduce deforestation/CO₂; recycle instead of landfill'],trophic:['Producer1 → primary2 → secondary3 → tertiary4','Apex: no predator in the stated context','Decomposers receive material across feeding levels'],biomass:['About1% of incident light energy captured','About10% biomass transfer is a guide, not a fixed key','Fraction transferred ×100 gives percentage efficiency'],'food-security':['Demand: population, diets and transport','Production: pests, pathogens, rains and input costs','Access: conflict, water, distribution and affordability']};
export function feedingTopicFigure(o={}){if(o.concealed)return eco5SVG(T(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');let k=o.kind||'conservation',base=k.replace(/-(model|data)$/,'');if(k==='conservation-model')return planFigure(o);if(base==='pyramids')return pyramidFigure(o);if(k==='biomass-model')return allocationFigure(o);if(k==='food-security-model')return supplyFigure(o);if(base==='trophic'&&o.state==='2'||k==='trophic-model')return decomposerFigure(o.progress??0);if(base==='trophic'&&o.state==='0')return feedingFigure(o.progress??0);let r=rows[base]||rows.conservation;return eco5SVG(T(280,35,'Connect the supplied evidence and mechanism',21)+r.map((s,i)=>T(280,130+i*90,s,16)).join('')+T(280,430,'Original teaching comparison · boundaries and context matter',13),r.join('. '));}
